// Só dispara com o número conectado na Evolution. Se caiu, não pega lead da fila.
// Avisa o Márcio só quando o estado muda (caiu / voltou). O último estado fica no Redis (weap:disparo:conexao:Weap-0859).
// Se a checagem não responder, segue como antes (o Verifica WhatsApp ainda protege).
const instancia = 'Weap-0859';
const r = $('Checa conexão').first().json || {};
const estado = (r.instance && r.instance.state) || r.state || '';
const conectado = estado ? estado === 'open' : true;
const ultimo = String($input.first().json.ultimo || '');
const novo = conectado ? 'ok' : 'caiu';
let aviso = '';
if (estado && novo !== ultimo) {
  if (novo === 'caiu') aviso = `⚠️ O número ${instancia} caiu na Evolution (estado: ${estado}). O disparo dele está parado e volta sozinho quando o número reconectar.`;
  else if (ultimo === 'caiu') aviso = `✅ O número ${instancia} reconectou na Evolution e o disparo dele voltou.`;
}
const gravar = !!estado && novo !== ultimo;
return [{ json: { conectado, estado: estado || 'sem resposta', aviso, gravar, novo } }];
